require __DIR__.'/auth.php';requireLogin();
$user=currentUser();$uid=(int)$_SESSION['user_id'];$today=date('Y-m-d');$weekStart=date('Y-m-d',strtotime('monday this week'));$weekEnd=date('Y-m-d',strtotime('sunday this week'));
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$date=trim($_POST['weight_date']??'');$weight=is_numeric($_POST['weight_kg']??null)?(float)$_POST['weight_kg']:0;$notes=trim($_POST['weight_notes']??'');$d=DateTime::createFromFormat('Y-m-d',$date);if($d&&$d->format('Y-m-d')===$date&&$weight>=20&&$weight<=400&&mb_strlen($notes)<=250){$q=$db->prepare('INSERT INTO weights(user_id,weight_kg,weight_date,notes,created_at) VALUES(?,?,?,?,?)');$q->execute([$uid,$weight,$date,$notes,date('Y-m-d H:i:s')]);header('Location: health.php?weight_saved=1');exit;}}
$q=$db->prepare('SELECT COALESCE(SUM(calories),0) cal,COALESCE(SUM(protein),0) protein,COALESCE(SUM(carbs),0) carbs,COALESCE(SUM(fat),0) fat,COUNT(*) entries FROM lunches WHERE user_id=? AND lunch_date=?');$q->execute([$uid,$today]);$todayN=$q->fetch();
$q=$db->prepare('SELECT COALESCE(SUM(calories),0) cal,COALESCE(SUM(protein),0) protein,COALESCE(SUM(carbs),0) carbs,COALESCE(SUM(fat),0) fat,COUNT(DISTINCT lunch_date) days FROM lunches WHERE user_id=? AND lunch_date BETWEEN ? AND ?');$q->execute([$uid,$weekStart,$weekEnd]);$weekN=$q->fetch();
$q=$db->prepare('SELECT weight_kg,weight_date,notes FROM weights WHERE user_id=? ORDER BY weight_date DESC,id DESC LIMIT 12');$q->execute([$uid]);$weights=$q->fetchAll();$latest=$weights[0]['weight_kg']??null;$previous=$weights[1]['weight_kg']??null;$weightChange=($latest!==null&&$previous!==null)?$latest-$previous:null;
$q=$db->prepare('SELECT DISTINCT lunch_date FROM lunches WHERE user_id=? AND lunch_date<=? ORDER BY lunch_date DESC LIMIT 90');$q->execute([$uid,$today]);$loggedDates=array_column($q->fetchAll(),'lunch_date');$streak=0;$cursor=new DateTime($today);$set=array_flip($loggedDates);while(isset($set[$cursor->format('Y-m-d')])){$streak++;$cursor->modify('-1 day');}
$achievements=[];if($streak>=3)$achievements[]=['🔥','3-Day Streak'];if($streak>=7)$achievements[]=['🔥','7-Day Streak'];if(count($loggedDates)>=10)$achievements[]=['📅','10 Logged Days'];if(count($loggedDates)>=30)$achievements[]=['🏆','30 Logged Days'];if($todayN['protein']>=50)$achievements[]=['💪','Protein Goal Day'];if($todayN['entries']>=6)$achievements[]=['⭐','Six Meals Logged'];
$recommendations=[];if((float)$todayN['protein']<50)$recommendations[]='Add a protein-rich food such as eggs, fish, chicken, dal, milk or curd to your next meal.';if((float)$todayN['entries']<3)$recommendations[]='Your log is light today. Try recording each meal/snack to improve your weekly insights.';if((float)$todayN['cal']>0&&$todayN['cal']<1200)$recommendations[]='Your recorded calories are currently low; make sure your meals are adequate for your personal needs.';if(!$recommendations)$recommendations[]='Great logging today. Keep a balanced mix of protein, vegetables, fruits and staple foods.';
