<section class="card"><div class="head"><h2>🤖 Smart Recommendations</h2></div><?php foreach($recommendations as $r):?><div class="recommend">💡 <?=h($r)?></div><?php endforeach;?></section>
<section class="card"><div class="head"><div><h2>📋 Weekly Health Summary</h2><small><?=h(date('d-m-Y',strtotime($weekStart)))?> → <?=h(date('d-m-Y',strtotime($weekEnd)))?></small></div></div><div class="health-grid"><div class="metric"><strong><?=number_format((float)$weekN['cal'],0)?></strong><span>Weekly kcal</span></div><div class="metric"><strong><?=number_format((float)$weekN['protein'],1)?>g</strong><span>Weekly protein</span></div><div class="metric"><strong><?=number_format((float)$weekN['days'],0)?>/7</strong><span>Days logged</span></div><div class="metric"><strong><?=$streak?></strong><span>Current streak</span></div></div></section>
<section class="card"><div class="head"><div><h2>⚖️ Weight Progress</h2><small>Track your own measurements over time.</small></div><?php if($latest!==null):?><span class="pill"><?=h(number_format((float)$latest,1))?> kg</span><?php endif;?></div><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><div class="grid"><div><label>Date</label><input type="date" name="weight_date" value="<?=h($today)?>" required></div><div><label>Weight (kg)</label><input type="number" name="weight_kg" min="20" max="400" step="0.1" required placeholder="e.g. 60.5"></div><div class="full"><label>Note</label><input name="weight_notes" maxlength="250" placeholder="Optional note"></div></div><button class="save">Add Weight</button></form><?php if($weightChange!==null):?><p class="muted" style="margin-top:12px">Latest change: <strong><?=($weightChange>0?'+':'').number_format($weightChange,1)?> kg</strong> compared with the previous record.</p><?php endif;?><?php if($weights):?><div class="weight-list" style="margin-top:12px"><?php foreach($weights as $w):?><div class="weight-row"><span><?=h(date('d-m-Y',strtotime($w['weight_date'])))?></span><strong><?=h(number_format((float)$w['weight_kg'],1))?> kg</strong></div><?php endforeach;?></div><?php endif;?></section>
<section class="card"><div class="head"><div><h2>🏆 Achievements</h2><small>Earned automatically from your log.</small></div></div><?php if($achievements):?><div class="ach"><?php foreach($achievements as $a):?><span><?=$a[0]?> <?=h($a[1])?></span><?php endforeach;?></div><?php else:?><p class="muted">Keep logging meals to unlock your first achievement.</p><?php endif;?></section>
